-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.draft_pattern(schema_name text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select '\m' || schema_name || '\.('
         || coalesce(string_agg(distinct regexp_replace(m.name, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g'), '|'), '$^')
         || ')\M'
    from public.draft_mirror() m;
$function$;
